#include <stdlib.h>
#include <string.h>
#include <omp.h>

#ifdef __AVX512F__
#include <immintrin.h>
#define MR 12
#define NR 32
#define KC 160
#define MCP 8
#define NCPMAX 8
#else
#define MR 6
#define NR 16
#define KC 256
#define MCP 16
#define NCPMAX 16
#endif

#ifdef __AVX512F__
static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict C, int ldc, int mr, int nr, int first)
{
    for (int i = 0; i < mr; i++) {
        _mm_prefetch((const char *)(C + (size_t)i * ldc), _MM_HINT_T0);
        _mm_prefetch((const char *)(C + (size_t)i * ldc + 16), _MM_HINT_T0);
    }
#define DECL(i) __m512 c##i##_0 = _mm512_setzero_ps(), c##i##_1 = _mm512_setzero_ps();
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    DECL(6) DECL(7) DECL(8) DECL(9) DECL(10) DECL(11)
#undef DECL
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
        _mm_prefetch((const char *)(a + MR * 8), _MM_HINT_T0);
#define FM(i) { __m512 t = _mm512_set1_ps(a[i]); \
        c##i##_0 = _mm512_fmadd_ps(t, b0, c##i##_0); \
        c##i##_1 = _mm512_fmadd_ps(t, b1, c##i##_1); }
        FM(0) FM(1) FM(2) FM(3) FM(4) FM(5)
        FM(6) FM(7) FM(8) FM(9) FM(10) FM(11)
#undef FM
        a += MR;
        b += NR;
    }
    __mmask16 m0, m1;
    if (nr >= 32) { m0 = 0xFFFF; m1 = 0xFFFF; }
    else if (nr >= 16) { m0 = 0xFFFF; m1 = (__mmask16)((1u << (nr - 16)) - 1); }
    else { m0 = (__mmask16)((1u << nr) - 1); m1 = 0; }
#define ST(i) if (i < mr) { float *p = C + (size_t)(i) * ldc; \
        if (first) { \
            _mm512_mask_storeu_ps(p, m0, c##i##_0); \
            _mm512_mask_storeu_ps(p + 16, m1, c##i##_1); \
        } else { \
            _mm512_mask_storeu_ps(p, m0, _mm512_add_ps(_mm512_maskz_loadu_ps(m0, p), c##i##_0)); \
            _mm512_mask_storeu_ps(p + 16, m1, _mm512_add_ps(_mm512_maskz_loadu_ps(m1, p + 16), c##i##_1)); \
        } }
    ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
    ST(6) ST(7) ST(8) ST(9) ST(10) ST(11)
#undef ST
}
#else
typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict C, int ldc, int mr, int nr, int first)
{
    for (int i = 0; i < mr; i++)
        __builtin_prefetch(C + (size_t)i * ldc, 1);

    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1) do { \
            v8u *p0 = (v8u *)(C + (size_t)(r) * ldc); \
            v8u *p1 = (v8u *)(C + (size_t)(r) * ldc + 8); \
            if (first) { *p0 = x0; *p1 = x1; } \
            else { *p0 += x0; *p1 += x1; } \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        v8 t[MR][2] __attribute__((aligned(32)));
        t[0][0] = c00; t[0][1] = c01; t[1][0] = c10; t[1][1] = c11;
        t[2][0] = c20; t[2][1] = c21; t[3][0] = c30; t[3][1] = c31;
        t[4][0] = c40; t[4][1] = c41; t[5][0] = c50; t[5][1] = c51;
        const float *tf = (const float *)t;
        for (int i = 0; i < mr; i++) {
            float *cr = C + (size_t)i * ldc;
            const float *tr = tf + i * NR;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tr[j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tr[j];
        }
    }
}
#endif

static float *gA, *gB;
static size_t capA, capB;

static float *grow(float **p, size_t *cap, size_t nfloats)
{
    size_t bytes = (nfloats * sizeof(float) + 63) & ~(size_t)63;
    if (bytes > *cap) {
        free(*p);
        *p = (float *)aligned_alloc(64, bytes);
        *cap = bytes;
    }
    return *p;
}

static void pack_a_panel(const float *A, int n, int row0, int p0, int kc,
                         float *restrict dst)
{
    int mr = n - row0 < MR ? n - row0 : MR;
    if (mr == MR) {
        const float *s[MR];
        for (int r = 0; r < MR; r++)
            s[r] = A + (size_t)(row0 + r) * n + p0;
        for (int k = 0; k < kc; k++) {
            float *d = dst + (size_t)k * MR;
            for (int r = 0; r < MR; r++) d[r] = s[r][k];
        }
    } else {
        for (int k = 0; k < kc; k++) {
            float *d = dst + (size_t)k * MR;
            for (int r = 0; r < MR; r++)
                d[r] = r < mr ? A[(size_t)(row0 + r) * n + p0 + k] : 0.0f;
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npA = (n + MR - 1) / MR;
    int npB = (n + NR - 1) / NR;
    int nkb = (n + KC - 1) / KC;
    float *Ap = grow(&gA, &capA, (size_t)npA * MR * n);
    float *Bp = grow(&gB, &capB, (size_t)npB * NR * n);

    int nth = omp_get_max_threads();
    int nib = (npA + MCP - 1) / MCP;
    int want = (4 * nth + nib - 1) / nib;
    if (want < 1) want = 1;
    int ncp = (npB + want - 1) / want;
    if (ncp > NCPMAX) ncp = NCPMAX;
    if (ncp < 1) ncp = 1;
    int njb = (npB + ncp - 1) / ncp;
    int ntasks = nib * njb;

    #pragma omp parallel
    {
        #pragma omp for collapse(2) schedule(static) nowait
        for (int kb = 0; kb < nkb; kb++) {
            for (int ip = 0; ip < npA; ip++) {
                int p0 = kb * KC;
                int kc = n - p0 < KC ? n - p0 : KC;
                float *dst = Ap + (size_t)p0 * npA * MR + (size_t)ip * kc * MR;
                pack_a_panel(A, n, ip * MR, p0, kc, dst);
            }
        }

        #pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nkb; kb++) {
            for (int jp = 0; jp < npB; jp++) {
                int p0 = kb * KC;
                int kc = n - p0 < KC ? n - p0 : KC;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p0 * npB * NR + (size_t)jp * kc * NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(p0 + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    int j = 0;
                    for (; j < nr; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / njb, jb = t % njb;
            int ip0 = ib * MCP;
            int ip1 = ip0 + MCP < npA ? ip0 + MCP : npA;
            int jp0 = jb * ncp;
            int jp1 = jp0 + ncp < npB ? jp0 + ncp : npB;
            for (int kb = 0; kb < nkb; kb++) {
                int p0 = kb * KC;
                int kc = n - p0 < KC ? n - p0 : KC;
                const float *abase = Ap + (size_t)p0 * npA * MR;
                const float *bbase = Bp + (size_t)p0 * npB * NR;
                for (int jp = jp0; jp < jp1; jp++) {
                    int jj = jp * NR;
                    int nr = n - jj < NR ? n - jj : NR;
                    const float *bp = bbase + (size_t)jp * kc * NR;
                    for (int ip = ip0; ip < ip1; ip++) {
                        int ii = ip * MR;
                        int mr = n - ii < MR ? n - ii : MR;
                        kernel(kc, abase + (size_t)ip * kc * MR, bp,
                               C + (size_t)ii * n + jj, n, mr, nr, kb == 0);
                    }
                }
            }
        }
    }
}
